"""Shared test fixtures.

- Settings are built from defaults only (no `.env`, no real env vars).
- The DB is an in-memory SQLite.
- Any network connection to a non-local address fails the test (`no_network`, autouse).
"""

import socket
from collections.abc import Iterator

import pytest
from fastapi.testclient import TestClient
from sqlalchemy.engine import Engine
from sqlmodel import Session

from app.config import Settings, get_settings
from app.db import get_session, init_db, make_engine
from app.main import create_app

_LOCAL_HOSTS = {"localhost", "127.0.0.1", "::1", "testserver"}


class NetworkBlocked(RuntimeError):
    pass


def _host_of(address) -> str | None:
    if isinstance(address, tuple) and address:
        return str(address[0])
    return None  # unix sockets etc.


@pytest.fixture(autouse=True)
def no_network(monkeypatch) -> list[str]:
    """Block (and record) every non-local connection. Returns the list of blocked hosts."""
    blocked: list[str] = []

    # A local proxy would turn a "localhost" connection into a real outbound one.
    for var in ("HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "http_proxy", "https_proxy", "all_proxy"):
        monkeypatch.delenv(var, raising=False)
    real_connect = socket.socket.connect
    real_connect_ex = socket.socket.connect_ex
    real_getaddrinfo = socket.getaddrinfo

    def guard(host):
        if host is not None and host not in _LOCAL_HOSTS:
            blocked.append(host)
            raise NetworkBlocked(f"Real network call attempted in a test: {host}")

    def connect(self, address):
        guard(_host_of(address))
        return real_connect(self, address)

    def connect_ex(self, address):
        guard(_host_of(address))
        return real_connect_ex(self, address)

    def getaddrinfo(host, *args, **kwargs):
        guard(host if isinstance(host, str) else None)
        return real_getaddrinfo(host, *args, **kwargs)

    real_sendto = socket.socket.sendto

    def sendto(self, data, *args):
        guard(_host_of(args[-1]) if args else None)  # UDP (e.g. DNS queries)
        return real_sendto(self, data, *args)

    monkeypatch.setattr(socket.socket, "connect", connect)
    monkeypatch.setattr(socket.socket, "sendto", sendto)
    monkeypatch.setattr(socket.socket, "connect_ex", connect_ex)
    monkeypatch.setattr(socket, "getaddrinfo", getaddrinfo)
    return blocked


@pytest.fixture
def clean_env(monkeypatch):
    """Remove any real env vars that map to Settings fields."""
    for name in Settings.model_fields:
        monkeypatch.delenv(name.upper(), raising=False)


@pytest.fixture
def make_settings(clean_env):
    def _make(**overrides) -> Settings:
        overrides.setdefault("database_url", "sqlite://")
        return Settings(_env_file=None, **overrides)

    return _make


@pytest.fixture
def settings(make_settings) -> Settings:
    return make_settings()


@pytest.fixture
def engine(settings) -> Engine:
    eng = make_engine(settings.database_url)
    init_db(eng)
    return eng


@pytest.fixture
def session(engine) -> Iterator[Session]:
    with Session(engine) as s:
        yield s


@pytest.fixture
def client(settings, engine) -> Iterator[TestClient]:
    app = create_app(run_lifespan=False)

    def _session():
        with Session(engine) as s:
            yield s

    app.dependency_overrides[get_settings] = lambda: settings
    app.dependency_overrides[get_session] = _session
    with TestClient(app) as c:
        yield c
import json
from pathlib import Path

import pytest

from app.agents.claude_client import FixtureClaudeClient

SELLERS = Path(__file__).parent / "fixtures" / "sellers"


@pytest.mark.parametrize("name", ["meera_cakes", "tiffin_service", "tailor"])
def test_seller_fixture_shape(name):
    data = json.loads((SELLERS / f"{name}.json").read_text(encoding="utf-8"))
    assert data["id"] == name
    assert len(data["description"]) > 100
    lines = data["price_list"].splitlines()
    assert len(lines) >= 5
    assert sum("₹" in line for line in lines) >= 5


def test_reader_fixture_loads_by_default():
    out = FixtureClaudeClient().ask_json(fixture="reader_meera_cakes", tier="strong", system="", user="")
    assert out["business_name"] == "Meera's Home Cakes"
    assert all(p["price_inr"] > 0 for p in out["products"])
"""One helper for writing audit events."""

from sqlmodel import Session

from app.models import AuditEvent


def record(
    session: Session,
    *,
    actor: str,
    action: str,
    result: str,
    target: str = "",
    detail: str = "",
    business_id: int | None = None,
) -> AuditEvent:
    event = AuditEvent(
        business_id=business_id,
        actor=actor,
        action=action,
        target=target,
        result=result,
        detail=detail,
    )
    session.add(event)
    session.commit()
    session.refresh(event)
    return event
"""Internal endpoints (called by Caddy on the private network, not exposed publicly)."""

import re
from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query
from sqlmodel import Session, select

from app.config import Settings, get_settings
from app.db import get_session
from app.models import Business

router = APIRouter(prefix="/internal", tags=["internal"])

_HOSTNAME = re.compile(r"^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)*$")


def is_allowed_tls_domain(domain: str, settings: Settings, session: Session) -> bool:
    """True only for the app domain, a seller subdomain in the DB, or a seller domain in the DB."""
    d = domain.strip().lower().rstrip(".")
    if not _HOSTNAME.match(d):
        return False
    app_domain = settings.app_domain.lower().rstrip(".")
    if d == app_domain:
        return True
    suffix = "." + app_domain
    if d.endswith(suffix):
        label = d[: -len(suffix)]
        if "." in label:
            return False
        return session.exec(select(Business.id).where(Business.subdomain == label)).first() is not None
    return session.exec(select(Business.id).where(Business.domain == d)).first() is not None


@router.get("/tls-ask")
def tls_ask(
    settings: Annotated[Settings, Depends(get_settings)],
    session: Annotated[Session, Depends(get_session)],
    domain: Annotated[str, Query(max_length=253)] = "",
) -> dict:
    """Caddy on-demand TLS `ask` hook: 200 = issue a certificate, anything else = refuse."""
    if not is_allowed_tls_domain(domain, settings, session):
        raise HTTPException(status_code=404, detail="unknown domain")
    return {"ok": True}
import { useEffect, useState } from "react";

type Health = { ok: boolean; env: string };
type State =
  | { kind: "loading" }
  | { kind: "ok"; health: Health }
  | { kind: "error"; message: string };

export default function App() {
  const [state, setState] = useState<State>({ kind: "loading" });

  useEffect(() => {
    fetch("/api/health")
      .then(async (r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        const health = (await r.json()) as Health;
        setState(health.ok ? { kind: "ok", health } : { kind: "error", message: "Server says not ok" });
      })
      .catch((e: unknown) => setState({ kind: "error", message: String(e) }));
  }, []);

  return (
    <main className="page">
      <h1>LaunchWitness</h1>
      <p className="tagline">
        Describe your business. We launch it on GoDaddy and prove everything works before your first
        customer arrives.
      </p>

      <section className={`status status-${state.kind}`} aria-live="polite">
        {state.kind === "loading" && <p>Checking that LaunchWitness is running…</p>}
        {state.kind === "ok" && <p>✅ LaunchWitness is running and ready.</p>}
        {state.kind === "error" && <p>⚠️ LaunchWitness isn't responding right now. Please try again in a minute.</p>}

        <details>
          <summary>Details</summary>
          <pre>
            {state.kind === "ok" && JSON.stringify(state.health, null, 2)}
            {state.kind === "error" && state.message}
            {state.kind === "loading" && "GET /api/health …"}
          </pre>
        </details>
      </section>
    </main>
  );
}
