+  .card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px; }
+  .facts { display: grid; gap: 12px; }
+  .facts dt { font-size: 13px; color: var(--muted); }
+  .facts dd { margin: 0; font-weight: 600; }
+  .pay { display: grid; gap: 16px; align-items: center; }
+  .pay svg { width: 180px; height: 180px; background: #fff; border-radius: 10px; }
+  .upi-id { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; background: var(--brand-soft);
+    padding: 2px 8px; border-radius: 6px; word-break: break-all; }
+  form .row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 0; }
+  form .row + .row { border-top: 1px solid var(--line); }
+  form .row label { flex: 1; }
+  form .row small { display: block; color: var(--muted); }
+  input[type=number] { width: 72px; }
+  input, textarea { font: inherit; padding: 10px 12px; border: 1px solid #d6c8b9; border-radius: 10px;
+    background: #fff; color: var(--ink); }
+  input:focus, textarea:focus, .btn:focus-visible { outline: 3px solid #f6ad7b; outline-offset: 1px; }
+  .field { display: grid; gap: 6px; margin-top: 14px; }
+  .field label { font-weight: 600; font-size: 15px; }
+  .field input, .field textarea { width: 100%; }
+  .hint { font-size: 14px; color: var(--muted); }
+  .error { background: #fef2f2; color: #991b1b; border: 1px solid #fecaca; padding: 10px 12px; border-radius: 10px; }
+  .ok { background: #f0fdf4; border: 1px solid #bbf7d0; }
+  .hp { position: absolute; left: -9999px; width: 1px; height: 1px; overflow: hidden; }
+  footer { padding: 28px 0 40px; color: var(--muted); font-size: 14px; border-top: 1px solid var(--line); }
+  footer .wrap { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; }
+  .prose p { margin: 0 0 12px; }
+  @media (min-width: 640px) {
+    .facts { grid-template-columns: 1fr 1fr; }
+    .pay { grid-template-columns: 180px 1fr; }
+  }
+</style>
+</head>
+<body>
+<header class="bar">
+  <div class="wrap">
+    <a class="brand" href="/">{{ p.name }}</a>
+    {% if page == "home" %}<a class="btn btn-primary btn-sm" href="#order">Order now</a>{% else %}<a class="btn btn-ghost btn-sm" href="/">Back to menu</a>{% endif %}
+  </div>
+</header>
+
+<main class="wrap">
+{% if page == "home" %}
+  <div class="hero">
+    <h1>{{ p.name }}</h1>
+    {% if p.tagline %}<p class="tagline">{{ p.tagline }}</p>{% endif %}
+    {% if p.area %}<p class="area">📍 {{ p.area }}</p>{% endif %}
+    <div class="cta">
+      <a class="btn btn-primary" href="#order">Place an order</a>
+      {% if whatsapp_url %}<a class="btn btn-wa" href="{{ whatsapp_url }}" target="_blank" rel="noopener">Order on WhatsApp</a>{% endif %}
+    </div>
+  </div>
+
+  <section id="menu" aria-labelledby="menu-h">
+    <h2 id="menu-h">Menu &amp; prices</h2>
+    {% for cat in categories %}
+      <h3 class="cat">{{ cat.name }}</h3>
+      <ul class="menu">
+        {% for _i, item in cat.items %}
+        <li>
+          <div><div class="name">{{ item.name }}</div>{% if item.description %}<div class="desc">{{ item.description }}</div>{% endif %}</div>
+          <div class="price">{{ item.price_inr | inr }}</div>
+        </li>
+        {% endfor %}
+      </ul>
+    {% endfor %}
+  </section>
+
+  {% if p.about %}
+  <section id="about" aria-labelledby="about-h">
+    <h2 id="about-h">About us</h2>
+    <div class="prose">{% for para in p.about.split("\n") if para.strip() %}<p>{{ para }}</p>{% endfor %}</div>
+  </section>
+  {% endif %}
+
+  <section id="visit" aria-labelledby="visit-h">
+    <h2 id="visit-h">Hours &amp; contact</h2>
+    <dl class="card facts">
+      {% if p.hours %}<div><dt>Open</dt><dd>{{ p.hours }}</dd></div>{% endif %}
+      {% if p.area %}<div><dt>Where</dt><dd>{{ p.area }}</dd></div>{% endif %}
+      {% if p.phone %}<div><dt>Call</dt><dd><a href="tel:{{ p.phone | replace(' ', '') }}">{{ p.phone }}</a></dd></div>{% endif %}
+      {% if whatsapp_url %}<div><dt>WhatsApp</dt><dd><a href="{{ whatsapp_url }}" target="_blank" rel="noopener">Message us</a></dd></div>{% endif %}
+    </dl>
+  </section>
+
+  {% if upi %}
+  <section id="pay" aria-labelledby="pay-h">
+    <h2 id="pay-h">Pay with UPI</h2>
+    <div class="card pay">
+      {{ upi_qr }}
+      <div>
+        <p style="margin-top:0">Scan with any UPI app (GPay, PhonePe, Paytm, BHIM) to pay {{ p.name }}.</p>
+        <p>UPI ID: <span class="upi-id">{{ p.upi_id }}</span></p>
+        <a class="btn btn-ghost btn-sm" href="{{ upi }}">Open UPI app</a>
+        <p class="hint">Please confirm the amount with us before paying.</p>
+      </div>
+    </div>
+  </section>
+  {% endif %}
+
+  <section id="order" aria-labelledby="order-h">
+    <h2 id="order-h">Place an order</h2>
+    <p class="hint">Choose what you'd like. We'll contact you to confirm the order, timing and payment. Nothing is charged here.</p>
+    {% if form_error %}<p class="error" role="alert">{{ form_error }}</p>{% endif %}
+    <form class="card" method="post" action="/order">
+      {% for cat in categories %}{% for i, item in cat.items %}
+      <div class="row">
+        <label for="qty_{{ i }}">{{ item.name }}<small>{{ item.price_inr | inr }}</small></label>
+        <input id="qty_{{ i }}" name="qty_{{ i }}" type="number" inputmode="numeric" min="0" max="50" step="1" value="{{ form.get('qty_' ~ i, 0) }}">
+      </div>
+      {% endfor %}{% endfor %}
+      <div class="field">
+        <label for="note">Anything else? (date needed, message on cake, size…)</label>
+        <textarea id="note" name="note" rows="3" maxlength="1000">{{ form.get('note', '') }}</textarea>
+      </div>
+      <div class="field">
+        <label for="customer_name">Your name</label>
+        <input id="customer_name" name="customer_name" required maxlength="80" autocomplete="name" value="{{ form.get('customer_name', '') }}">
+      </div>
+      <div class="field">
+        <label for="customer_phone">Your phone number</label>
+        <input id="customer_phone" name="customer_phone" required inputmode="tel" maxlength="20" autocomplete="tel" placeholder="98765 43210" value="{{ form.get('customer_phone', '') }}">
+      </div>
+      <div class="hp" aria-hidden="true"><label for="website">Leave empty</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div>
+      <p class="hint">By ordering you agree we use these details only to handle your order. <a href="/privacy">Privacy</a></p>
+      <button class="btn btn-primary" type="submit" style="width:100%">Send order</button>
+    </form>
+  </section>
+
+{% elif page == "thanks" %}
+  <div class="hero">
+    <h1>Thank you{% if order %}, {{ order.customer_name }}{% endif %}!</h1>
+    <p class="tagline">{{ p.name }} has received your order and will contact you soon to confirm it.</p>
+  </div>
+  {% if order %}
+  <section>
+    <h2>Your order</h2>
+    <ul class="menu">
+      {% for it in order["items"] %}<li><div class="name">{{ it.qty }} × {{ it.name }}</div><div class="price">{{ (it.qty * it.price_inr) | inr }}</div></li>{% endfor %}
+      {% if order["items"] %}<li><div class="name">Estimated total</div><div class="price">{{ order.total_inr | inr }}</div></li>{% endif %}
+    </ul>
+    {% if order.note %}<p class="hint">Your note: {{ order.note }}</p>{% endif %}
+    <p class="hint">The final amount (for example delivery) is confirmed by the shop.</p>
+    <div class="cta">{% if whatsapp_url %}<a class="btn btn-wa" href="{{ whatsapp_url }}" target="_blank" rel="noopener">Message on WhatsApp</a>{% endif %}<a class="btn btn-ghost" href="/">Back to menu</a></div>
+  </section>
+  {% endif %}
+
+{% elif page == "privacy" %}
+  <div class="hero"><h1>Privacy</h1><p class="tagline">How {{ p.name }} uses your details.</p></div>
+  <section class="prose">
+    <p><strong>What we collect.</strong> When you place an order on this site we collect your name, your phone number, what you ordered and any note you add. We don't use cookies for tracking and we don't run ads.</p>
+    <p><strong>Why.</strong> Only to prepare your order and contact you about it (to confirm timing, delivery and payment).</p>
+    <p><strong>Who sees it.</strong> Your order is sent by email to {{ p.name }}. It is stored securely by the service that runs this website, LaunchWitness, so the order isn't lost. We never sell or share your details for marketing.</p>
+    <p><strong>Payments.</strong> This site does not take payments. If you pay by UPI, the payment happens in your own UPI app.</p>
+    <p><strong>How long.</strong> Order details are kept for up to 12 months for our records, then deleted.</p>
+    <p><strong>Your choice.</strong> To see, correct or delete your details, contact us{% if p.phone %} on {{ p.phone }}{% endif %}{% if whatsapp_url %} or <a href="{{ whatsapp_url }}" target="_blank" rel="noopener">on WhatsApp</a>{% endif %}.</p>
+  </section>
+{% endif %}
+</main>
+
+<footer>
+  <div class="wrap">
+    <span>© {{ p.name }}{% if p.area %} · {{ p.area }}{% endif %}</span>
+    <span><a href="/privacy">Privacy</a> · Site by LaunchWitness</span>
+  </div>
+</footer>
+</body>
+</html>

