:root {
  --bg: #fbfaf7;
  --fg: #1d1d1b;
  --muted: #5c5b57;
  --ok-bg: #e7f5ec;
  --ok-fg: #1d6b3a;
  --err-bg: #fdecea;
  --err-fg: #9b2c1f;
  --card: #ffffff;
  --border: #e4e1da;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--fg);
  background: var(--bg);
}

body {
  margin: 0;
  background: var(--bg);
}

.page {
  max-width: 40rem;
  margin: 0 auto;
  padding: 3rem 1rem;
}

h1 {
  margin: 0 0 0.5rem;
  font-size: 2rem;
}

.tagline {
  color: var(--muted);
  font-size: 1.1rem;
  line-height: 1.5;
}

.status {
  margin-top: 2rem;
  padding: 1rem 1.25rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--card);
  font-size: 1.1rem;
}

.status-ok {
  background: var(--ok-bg);
  color: var(--ok-fg);
}

.status-error {
  background: var(--err-bg);
  color: var(--err-fg);
}

details {
  margin-top: 0.75rem;
  font-size: 0.9rem;
  color: var(--muted);
}

pre {
  white-space: pre-wrap;
  margin: 0.5rem 0 0;
}
